import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    capacity = int(data[0].strip())
    arr = [None] * capacity
    front = rear = count = 0
    out_lines = []
    for line in data[1:]:
        line = line.strip()
        if not line:
            continue
        if line == "exit":
            break
        parts = line.split()
        cmd = parts[0].lower()
        if cmd == "enqueue":
            if len(parts) < 2:
                continue
            if count == capacity:
                continue  # queue full, ignore
            try:
                val = int(parts[1])
            except:
                continue
            arr[rear] = val
            rear = (rear + 1) % capacity
            count += 1
        elif cmd == "dequeue":
            if count == 0:
                continue  # empty, ignore
            front = (front + 1) % capacity
            count -= 1
        elif cmd == "display":
            if count == 0:
                out_lines.append("")
            else:
                elems = [str(arr[(front + i) % capacity]) for i in range(count)]
                out_lines.append(" ".join(elems))
        # else ignore unknown commands
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
